function checkWinCondition() {
  if (gameState.player.health <= 0) {
    alert("You lost!");
    resetGame();
  } else if (gameState.player.position.x === gameState.map.width - 1 && gameState.player.position.y === gameState.map.height - 1) {
    alert("You won!");
    winCondition = true;
    resetGame();
  }
}

// Trigger win condition
setInterval(checkWinCondition, 5000);
